<?php $isEdit = !empty($recipe['id']); $title = $title ?? ($isEdit ? 'Edit Recipe' : 'Create Recipe'); ?><section class="container section narrow"><h1><?= e($title) ?></h1><form action="<?= e($formAction) ?>" method="post" enctype="multipart/form-data" class="stack-form recipe-form" data-recipe-form><?= \App\Util\Csrf::field() ?><section class="card"><h2>1. Basic info</h2><label>Title <input type="text" name="title" value="<?= e($recipe['title'] ?? '') ?>" required></label><label>Description <textarea name="description" rows="4" required><?= e($recipe['description'] ?? '') ?></textarea></label><label>Categories <input type="text" name="categories" value="<?= e(implode(', ', $recipe['categories'] ?? [])) ?>" list="category-list" placeholder="Breakfast, Dessert"></label><datalist id="category-list"><?php foreach ($categories as $category): ?><option value="<?= e($category) ?>"><?php endforeach; ?></datalist><label>Tags <input type="text" name="tags" value="<?= e(implode(', ', $recipe['tags'] ?? [])) ?>" placeholder="quick, vegetarian"></label></section><section class="card two-col"><div><h2>2. Servings</h2><label>Servings <input type="number" name="servings" min="1" value="<?= e((string) ($recipe['servings'] ?? 4)) ?>"></label></div><div><h2>Yield</h2><label>Amount <input type="number" step="0.1" name="yield_amount" value="<?= e((string) ($recipe['yield_amount'] ?? '')) ?>"></label><label>Unit <input type="text" name="yield_unit" value="<?= e((string) ($recipe['yield_unit'] ?? '')) ?>" placeholder="cookies, loaves"></label></div></section><section class="card"><div class="section-header"><h2>3. Ingredients</h2><button type="button" class="button button-secondary" data-add-ingredient>Add ingredient</button></div><div id="ingredient-rows"><?php foreach (($recipe['ingredients'] ?? []) as $ingredient): ?><div class="ingredient-row"><input type="text" name="ingredient_name[]" value="<?= e((string) ($ingredient['name'] ?? '')) ?>" placeholder="Ingredient" data-ingredient-autocomplete><input type="number" step="0.01" name="ingredient_quantity[]" value="<?= e((string) ($ingredient['quantity'] ?? '')) ?>" placeholder="Qty"><input type="text" name="ingredient_unit[]" value="<?= e((string) ($ingredient['unit'] ?? '')) ?>" placeholder="Unit"><input type="text" name="ingredient_preparation[]" value="<?= e((string) ($ingredient['preparation'] ?? '')) ?>" placeholder="Preparation"><button type="button" class="button button-danger" data-remove-row>Remove</button></div><?php endforeach; ?></div></section><section class="card"><div class="section-header"><h2>4. Steps</h2><button type="button" class="button button-secondary" data-add-step>Add step</button></div><div id="step-rows"><?php foreach (($recipe['steps'] ?? ['']) as $step): ?><div class="step-row"><textarea name="steps[]" rows="3" placeholder="Describe this step"><?= e($step) ?></textarea><button type="button" class="button button-danger" data-remove-row>Remove</button></div><?php endforeach; ?></div></section><section class="card"><h2>5. Images</h2><?php if (!empty($recipe['images'])): ?><div class="recipe-gallery"><?php foreach ($recipe['images'] as $image): ?><img src="<?= e('/uploads/' . $image) ?>" alt="Recipe image"><?php endforeach; ?></div><?php endif; ?><label>Upload images <input type="file" name="images[]" accept="image/*" multiple></label></section><section class="card"><h2>6. Status</h2><label><select name="status"><option value="draft" <?= ($recipe['status'] ?? 'draft') === 'draft' ? 'selected' : '' ?>>Draft</option><option value="published" <?= ($recipe['status'] ?? '') === 'published' ? 'selected' : '' ?>>Published</option></select></label></section><div class="form-actions"><button class="button" type="submit">Save recipe</button></div></form><?php if ($isEdit): ?><form action="/recipe/<?= e($recipe['id']) ?>/delete" method="post" class="inline-form"><?= \App\Util\Csrf::field() ?><button class="button button-danger" type="submit">Delete recipe</button></form><?php endif; ?></section>
